add_filter( 'pre_option_woocommerce_hide_out_of_stock_items', 'perfectpixel_show_out_of_stock_in_categories' );

function perfectpixel_show_out_of_stock_in_categories( $value ) {
	$ids = wp_parse_id_list( '{{show_oos_category_ids}}' );
	// The product query reads this option during pre_get_posts, after the main query was parsed.
	if ( $ids && ! is_admin() && isset( $GLOBALS['wp_query'] ) && $GLOBALS['wp_query']->is_tax( 'product_cat', $ids ) ) {
		return 'no';
	}
	return $value; // false = use the saved setting.
}
